files.content:
.root {
  --vt-surface: #ffffff;
  --vt-surface-2: #f9f9f9;
  --vt-surface-deep: #171819;
  --vt-ink: #171819;
  --vt-ink-soft: #666262;
  --vt-on-deep: #ffffff;
  --vt-accent: #d62c0b;
  --vt-on-accent: #ffffff;
  --vt-accent-ink: #c22e0a;
  --vt-accent-on-deep: #f13a11;
  --vt-line: #efebeb;

  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  color: var(--vt-ink);
  background: var(--vt-surface);
  line-height: 1.5;
}

.root *,
.root *::before,
.root *::after {
  box-sizing: border-box;
}

.root a {
  color: var(--vt-ink);
  text-decoration: none;
  transition: color 0.3s ease;
}

.root a:hover,
.root a:active,
.root a:focus {
  color: var(--vt-accent);
  outline: none;
}

.root a:focus-visible {
  outline: 2px solid var(--vt-accent);
  outline-offset: 2px;
}

.container {
  width: 100%;
  max-width: 1140px;
  margin: 0 auto;
  padding: 0 1rem;
}

/* NAV */
.nav {
  background: var(--vt-surface-deep);
  padding: 1rem 0;
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  z-index: 1000;
}

.navIn {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
}

.logo {
  color: var(--vt-on-deep);
  font-size: 1.75rem;
  font-weight: 700;
  line-height: 1;
}

.brand {
  display: inline-block;
}

.navLinks {
  display: flex;
  gap: 1.5rem;
  align-items: center;
}

.navLinks a {
  color: var(--vt-on-deep);
  font-size: 0.875rem;
  font-weight: 400;
  text-transform: uppercase;
  padding: 0.25rem 0.5rem;
  letter-spacing: 0.5px;
}

.navLinks a:hover,
.navLinks a:focus {
  color: var(--vt-accent-on-deep);
}

/* HERO */
.hero {
  position: relative;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  background-color: var(--vt-surface-deep);
}

.heroBg {
  position: absolute;
  inset: 0;
  background-size: cover;
  background-position: top center;
  background-repeat: no-repeat;
  z-index: 1;
}

.heroOverlay {
  position: absolute;
  inset: 0;
  background: var(--vt-surface-deep);
  opacity: 0.85;
  z-index: 2;
}

.heroInner {
  position: relative;
  z-index: 3;
  text-align: center;
  padding: 2rem 1rem;
  max-width: 800px;
}

.heroKicker {
  color: var(--vt-on-deep);
  font-size: 1.375rem;
  font-weight: 300;
  text-transform: uppercase;
  letter-spacing: 2px;
  margin: 0 0 0.5rem;
  opacity: 0.9;
}

.heroTitle {
  color: var(--vt-on-deep);
  font-size: 3rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: -1px;
  line-height: 1.1;
  margin: 1rem 0;
}

.heroCtas {
  display: flex;
  gap: 1rem;
  justify-content: center;
  flex-wrap: wrap;
  margin-top: 2rem;
}

.btn {
  display: inline-block;
  border-radius: 2px;
  padding: 0.875rem 1.5rem;
  font-size: 0.875rem;
  font-weight: 400;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  white-space: nowrap;
  transition: all 0.3s ease;
}

.btnPrimary {
  background: var(--vt-accent);
  color: var(--vt-on-accent);
  border: 1px solid transparent;
}

.btnPrimary:hover,
.btnPrimary:focus {
  background: var(--vt-on-accent);
  color: var(--vt-accent);
  border-color: var(--vt-accent);
}

.btnOutline {
  background: transparent;
  color: var(--vt-on-deep);
  border: 1px solid var(--vt-accent);
}

.btnOutline:hover,
.btnOutline:focus {
  background: var(--vt-accent);
  color: var(--vt-on-accent);
  border-color: transparent;
}

/* FEATURE */
.feature {
  background: var(--vt-surface-deep);
  padding: 5rem 0;
}

.featureGrid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3rem;
  align-items: center;
}

.featureText {
  color: var(--vt-on-deep);
}

.headingLight {
  color: var(--vt-on-deep);
  font-size: 2.25rem;
  font-weight: 700;
  letter-spacing: -1px;
  margin: 0 0 1.5rem;
}

.paragraphLight {
  color: var(--vt-on-deep);
  font-size: 1.125rem;
  font-weight: 300;
  opacity: 0.85;
  margin: 0 0 2rem;
}

.hoursCard {
  border-left: 2px solid var(--vt-accent);
  padding-left: 3.5rem;
}

.hoursText {
  color: var(--vt-on-deep);
  font-size: 1.125rem;
  font-weight: 300;
  white-space: pre-line;
  opacity: 0.9;
}

/* ABOUT */
.about {
  background: var(--vt-surface-2);
  padding: 7rem 0;
}

.aboutGrid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
}

.aboutText {
  color: var(--vt-ink);
}

.headingDark {
  color: var(--vt-ink);
  font-size: 2.25rem;
  font-weight: 700;
  letter-spacing: -1px;
  margin: 0 0 1.5rem;
}

.paragraphDark {
  color: var(--vt-ink-soft);
  font-size: 1.125rem;
  font-weight: 300;
  margin: 0 0 1rem;
}

.aboutImageWrapper {
  border-radius: 4px;
  overflow: hidden;
  box-shadow: 6px 0 38px rgba(20, 20, 20, 0.1);
}

.aboutImage {
  display: block;
  width: 100%;
  height: auto;
  object-fit: cover;
}

/* CLASSES */
.classes {
  padding: 7rem 0;
  background: var(--vt-surface);
}

.sectionHeader {
  text-align: center;
  margin-bottom: 4rem;
}

.sectionKicker {
  color: var(--vt-ink-soft);
  font-size: 1.375rem;
  font-weight: 300;
  text-transform: uppercase;
  letter-spacing: 2px;
  margin: 0 0 0.5rem;
}

.classGrid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
}

.classCard {
  background: var(--vt-surface);
  border-radius: 0 0 2px 2px;
  box-shadow: 6px 0 38px rgba(20, 20, 20, 0.1);
  transition: transform 0.3s ease;
  display: flex;
  flex-direction: column;
}

.classCard:hover {
  transform: translateY(-5px);
}

.classImageWrap {
  overflow: hidden;
  border-radius: 2px 2px 0 0;
}

.classImage {
  display: block;
  width: 100%;
  height: auto;
  object-fit: cover;
  transition: transform 0.3s ease;
}

.classCard:hover .classImage {
  transform: scale(1.05);
}

.classInfo {
  background: var(--vt-surface);
  padding: 1.5rem 2rem;
  position: relative;
  flex: 1;
}

.classTitle {
  color: var(--vt-ink);
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: -1px;
  margin: 0 0 0.5rem;
}

.classDesc {
  color: var(--vt-ink-soft);
  font-size: 1rem;
  font-weight: 300;
  margin: 0;
}

.classPrice {
  background: var(--vt-accent);
  color: var(--vt-on-accent);
  border-radius: 50%;
  font-weight: 700;
  display: block;
  position: absolute;
  top: 1.5rem;
  right: 1.5rem;
  width: 3.5rem;
  height: 3.5rem;
  line-height: 3.5rem;
  text-align: center;
  font-size: 1rem;
}

.classDuration {
  display: block;
  margin-top: 1rem;
  color: var(--vt-ink-soft);
  font-size: 0.875rem;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

/* CONTACT */
.contact {
  padding: 7rem 0;
  background: var(--vt-surface-2);
}

.contactGrid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: start;
}

.form {
  display: flex;
  flex-direction: column;
  gap: 1.2rem;
}

.formInput,
.formTextarea {
  width: 100%;
  padding: 0.875rem 1rem;
  border: 1px solid var(--vt-line);
  border-radius: 2px;
  font-size: 1rem;
  color: var(--vt-ink);
  background: var(--vt-surface);
  transition: border-color 0.3s ease;
}

.formInput:focus,
.formTextarea:focus {
  outline: none;
  border-color: var(--vt-accent);
}

.formTextarea {
  resize: vertical;
  min-height: 150px;
}

.formSubmit {
  background: var(--vt-surface-deep);
  color: var(--vt-on-deep);
  border: none;
  border-radius: 2px;
  padding: 0.875rem 1.5rem;
  font-size: 0.875rem;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  cursor: pointer;
  transition: background 0.3s ease;
  align-self: flex-start;
}

.formSubmit:hover,
.formSubmit:focus {
  background: var(--vt-accent);
  color: var(--vt-on-accent);
}

.socialLinks {
  margin-top: 2rem;
}

/* FOOTER */
.footer {
  background: var(--vt-surface);
  border-top: 1px solid var(--vt-line);
  padding: 3rem 0;
  text-align: center;
}

.footerText {
  color: var(--vt-ink-soft);
  font-size: 1rem;
  margin: 0.5rem 0;
}

.footerText a {
  color: var(--vt-ink-soft);
  font-weight: 300;
}

.footerText a:hover,
.footerText a:focus {
  color: var(--vt-accent);
}

/* RESPONSIVE */
@media screen and (max-width: 992px) {
  .featureGrid,
  .aboutGrid,
  .contactGrid {
    grid-template-columns: 1fr;
    gap: 3rem;
  }

  .hoursCard {
    border-left: 0;
    padding-left: 0;
    border-top: 2px solid var(--vt-accent);
    padding-top: 2rem;
  }

  .classGrid {
    grid-template-columns: 1fr;
    max-width: 500px;
    margin: 0 auto;
  }

  .navIn {
    flex-direction: column;
    gap: 1rem;
  }

  .navLinks {
    flex-wrap: wrap;
    justify-content: center;
  }

  .heroTitle {
    font-size: 2.5rem;
  }
}

@media screen and (max-width: 767px) {
  .heroTitle {
    font-size: 2rem;
  }

  .heroKicker {
    font-size: 1rem;
  }

  .btn {
    padding: 0.75rem 1rem;
    font-size: 0.75rem;
  }

  .headingLight,
  .headingDark {
    font-size: 1.75rem;
  }

  .classPrice {
    width: 3rem;
    height: 3rem;
    line-height: 3rem;
    font-size: 0.875rem;
    top: 1rem;
    right: 1rem;
  }
}
